func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_exists", main != null, "La scena principale deve aprirsi senza errori"):
		return

	var cards: Array[Node] = []
	for child in main.get_children():
		if child.get_script() != null and child.get_script().resource_path.ends_with("card.gd"):
			cards.append(child)
		elif child.name.begins_with("Card") or child.filename == "res://card.tscn":
			cards.append(child)

	if cards.is_empty():
		var all_nodes := main.find_children("*", "", true, false)
		for node in all_nodes:
			if node.filename == "res://card.tscn" or (node.get_script() != null and node.get_script().resource_path.ends_with("card.gd")):
				cards.append(node)

	if not check("cards_count", cards.size() == 16, "Devono essere create esattamente 16 carte nella griglia"):
		return

	var value_counts := {}
	for card in cards:
		var val = get_prop(card, "value", null)
		if val != null:
			value_counts[val] = value_counts.get(val, 0) + 1

	var correct_pairs := true
	for i in range(1, 9):
		if value_counts.get(i, 0) != 2:
			correct_pairs = false
			break

	check("card_pairs", correct_pairs, "Ci devono essere 8 coppie di carte con valori da 1 a 8 (ogni valore deve comparire esattamente 2 volte)")

	var positions := []
	var distinct_pos := true
	for card in cards:
		var pos = get_prop(card, "position", Vector2.ZERO)
		if pos in positions:
			distinct_pos = false
		positions.append(pos)

	check("grid_positions", distinct_pos, "Le carte devono essere posizionate in punti diversi della schermata per formare una griglia")",
